export const meta = {
  name: 'verify-ipns-signature-findings',
  description: 'Re-verify S1/S2/S3 IPNS signature-storage security findings against current code',
  phases: [{ title: 'Verify', detail: 'one agent per finding (S1, S2, S3)' }],
}

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['finding', 'status', 'summary', 'evidence', 'driftFromTodo', 'remediationStillValid', 'notes'],
  properties: {
    finding: { type: 'string', enum: ['S1', 'S2', 'S3'] },
    status: { type: 'string', enum: ['open', 'partially-addressed', 'resolved', 'unclear'] },
    summary: { type: 'string', description: 'One-paragraph current-state verdict' },
    evidence: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['file', 'lines', 'observation'],
        properties: {
          file: { type: 'string' },
          lines: { type: 'string', description: 'Current line range, e.g. 60-65' },
          observation: { type: 'string', description: 'What the code does at these lines, quoting the key call' },
        },
      },
    },
    driftFromTodo: { type: 'string', description: 'How current code differs from the todo description (line drift, refactors, renames). "none" if unchanged.' },
    remediationStillValid: { type: 'boolean', description: 'Is the proposed Solution in the todo still the right fix given current code?' },
    notes: { type: 'string', description: 'Anything else relevant: blockers, dependencies, partial progress.' },
  },
}

const FINDINGS = [
  {
    key: 'S1',
    prompt: `You are verifying whether security finding S1 is STILL OPEN in the current CipherBox code (read-only verification, do not modify anything).

FINDING S1 (Medium) — publish does not validate signedRecord vs DTO fields:
"On publish the server only base64-decodes dto.record and stores it verbatim; the embedded CID/sequence inside the signed IPNS record are never parsed and compared against metadataCid / expectedSequenceNumber. A parser exists but is resolve-only and treats the DB columns as authoritative, only warning on mismatch."

PROPOSED FIX (todo): On publish, parse the embedded CID + sequence from the signed record and reject (400) when they disagree with the DTO's metadataCid / expectedSequenceNumber.

Read apps/api/src/ipns/ipns.service.ts in full. Focus on the publish path (base64 decode of dto.record, where it is stored, any parsing of the embedded signed-record CID/sequence). Also check the resolve path's parser to confirm it is resolve-only / warn-only. Determine the CURRENT status (open / partially-addressed / resolved / unclear), cite current file:line numbers (they may have drifted from the todo), note any drift, and say whether the proposed fix is still valid. Return ONLY the structured object.`,
  },
  {
    key: 'S2',
    prompt: `You are verifying whether security finding S2 is STILL OPEN in the current CipherBox code (read-only verification, do not modify anything).

FINDING S2 (Medium) — signature verification is downgrade-able:
"sdk-core throws on an invalid signature but skips verification entirely when fields are absent. The web path is weaker: it only logger.warn's even when a present signature is INVALID and still returns the CID. No resolve caller checks signatureVerified (all call sites read only .cid / .sequenceNumber), and the Rust client does not verify at all."

PROPOSED FIX (todo): Enforce verification — fail closed when a signature is present but invalid (web path must reject, not warn), have resolve callers honor signatureVerified, add verification to the Rust client, treat missing fields explicitly rather than silently skipping.

Read these in full:
- packages/sdk-core/src/ipns/index.ts (verification logic, throw vs skip)
- apps/web/src/services/ipns.service.ts (does it warn-and-return on invalid signature?)
- crates/api-client/src/ipns.rs (any signature verification at all?)
Also grep the repo for call sites that consume resolve results to check whether any honor a signatureVerified flag (vs only reading .cid / .sequenceNumber).
Determine CURRENT status per surface (sdk-core, web, rust, callers), cite current file:line numbers, note drift, say whether the fix is still valid. Return ONLY the structured object.`,
  },
  {
    key: 'S3',
    prompt: `You are verifying whether security finding S3 is STILL OPEN in the current CipherBox code (read-only verification, do not modify anything).

FINDING S3 (Medium) — inconsistent private-key zeroization; no caller-owns-key convention:
"Some paths zeroize generated keys (sdk-core file/index.ts, folder/index.ts), others do not (ipns/index.ts, vault/index.ts). Phase 44 introduced a contradiction: updateFileMetadata zeroizes a caller-passed key while its sibling updateFolderMetadataAndPublish does not. Rust uses Zeroizing/ZeroizeOnDrop widely but several unwrap paths return raw Vec<u8> keys with inconsistent caller cleanup (crates/crypto/src/ecies.rs, crates/fuse/src/lib.rs)."

PROPOSED FIX (todo): Establish and document a caller-owns-key convention across the SDK (zeroize at the buffer-owning boundary); reconcile the updateFileMetadata vs updateFolderMetadataAndPublish contradiction; audit the Rust unwrap paths returning raw key bytes.

Read the relevant regions of:
- packages/sdk-core/src/file/index.ts (zeroization in generated-key paths AND updateFileMetadata)
- packages/sdk-core/src/folder/index.ts (zeroization; updateFolderMetadataAndPublish)
- packages/sdk-core/src/ipns/index.ts (does it zeroize?)
- packages/sdk-core/src/vault/index.ts (does it zeroize?)
- crates/crypto/src/ecies.rs (Zeroizing usage; any raw Vec<u8> key returns)
- crates/fuse/src/lib.rs (raw key handling / cleanup)
Confirm whether the updateFileMetadata-vs-updateFolderMetadataAndPublish contradiction still exists. Determine CURRENT status, cite current file:line numbers, note drift, say whether the fix is still valid. Return ONLY the structured object.`,
  },
]

phase('Verify')
const results = await parallel(
  FINDINGS.map((f) => () =>
    agent(f.prompt, { label: `verify:${f.key}`, phase: 'Verify', schema: SCHEMA }).then((r) => ({ ...f, result: r }))
  )
)

return results.filter(Boolean).map((r) => r.result).filter(Boolean)

